script:
if doc.payment_type != "Receive":
    pass
else:
    for ref in doc.references:
        if ref.reference_doctype == "Sales Invoice" and ref.reference_name:
            claim_name = frappe.db.get_value(
                "SHA Claim",
                {"sales_invoice": ref.reference_name},
                "name"
            )
            if claim_name:
                current_paid = frappe.utils.flt(
                    frappe.db.get_value("SHA Claim", claim_name, "amount_paid")
                )
                new_paid = current_paid + frappe.utils.flt(ref.allocated_amount)
                frappe.db.set_value("SHA Claim", claim_name, "amount_paid", new_paid)

                claimed = frappe.utils.flt(
                    frappe.db.get_value("SHA Claim", claim_name, "amount_claimed")
                )
                rejected = frappe.utils.flt(
                    frappe.db.get_value("SHA Claim", claim_name, "rejected_amount")
                )

                if new_paid + rejected >= claimed:
                    frappe.db.set_value("SHA Claim", claim_name, "status", "Paid")

                frappe.msgprint(
                    "SHA Claim " + claim_name + " updated: amount_paid = " +
                    str(new_paid)
                )

if not doc.sales_invoice and doc.patient_name and doc.insurer and doc.service_type and doc.amount_claimed:

    insurer_prefix = doc.insurer or ""
    if "CIC" in insurer_prefix:
        prefix = "CIC"
    elif "KU" in insurer_prefix or "Kenyatta" in insurer_prefix:
        prefix = "KU"
    else:
        prefix = "CIC"

    item_map = {
        "Outpatient": prefix + " Outpatient Service",
        "Inpatient": prefix + " Inpatient Service",
        "Maternity": prefix + " Maternity Service",
        "Laboratory": prefix + " Laboratory Service",
        "Pharmacy": prefix + " Pharmacy Service",
    }
    item_code = item_map.get(doc.service_type)

    if not item_code or not frappe.db.exists("Item", item_code):
        frappe.msgprint("Item not found: " + str(item_code))
    else:
        si = frappe.new_doc("Sales Invoice")
        si.customer = doc.insurer
        si.posting_date = doc.date_of_service or frappe.utils.today()
        si.due_date = frappe.utils.add_days(si.posting_date, 30)
        si.append("items", {
            "item_code": item_code,
            "qty": 1,
            "rate": frappe.utils.flt(doc.amount_claimed),
        })
        si.insert(ignore_permissions=True)
        si.submit()
        frappe.db.set_value("Private Insurance Claim", doc.name, "sales_invoice", si.name)
        frappe.msgprint("Sales Invoice " + si.name + " created and linked.")

if doc.payment_type == "Receive":
    for ref in doc.references:
        if ref.reference_doctype == "Sales Invoice" and ref.reference_name:
            claim_name = frappe.db.get_value(
                "Private Insurance Claim",
                {"sales_invoice": ref.reference_name},
                "name"
            )
            if claim_name:
                current_paid = frappe.utils.flt(frappe.db.get_value("Private Insurance Claim", claim_name, "amount_paid"))
                new_paid = current_paid + frappe.utils.flt(ref.allocated_amount)
                frappe.db.set_value("Private Insurance Claim", claim_name, "amount_paid", new_paid)

                claimed = frappe.utils.flt(frappe.db.get_value("Private Insurance Claim", claim_name, "amount_claimed"))
                rejected = frappe.utils.flt(frappe.db.get_value("Private Insurance Claim", claim_name, "rejected_amount"))

                if new_paid + rejected >= claimed:
                    frappe.db.set_value("Private Insurance Claim", claim_name, "status", "Paid")

                frappe.msgprint("Claim " + claim_name + " updated: amount_paid = " + str(new_paid))
